import os
from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def _load_note(name: str) -> str | None:
    """Return the text of a readable regular file inside NOTES_DIR, or None."""
    try:
        base = NOTES_DIR.resolve()
        target = (base / name).resolve()
        if not target.is_relative_to(base) or not target.is_file():
            return None
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return None


def read_note(name: str) -> str:
    """Return the text of the file NOTES_DIR/name, or "" if it is missing or unreadable.

    name is untrusted. Only regular files that resolve to a location inside
    NOTES_DIR are read; anything else (absolute paths, "..", symlinks that
    escape NOTES_DIR, directories) yields "".
    """
    content = _load_note(name)
    return "" if content is None else content


def count_readable(names: list[str]) -> int:
    """Count the names that refer to readable regular files inside NOTES_DIR.

    Names are untrusted and may not reach any file outside NOTES_DIR.
    Missing, unreadable, non-file, or escaping names are not counted.
    """
    return sum(1 for name in names if _load_note(name) is not None)


def _write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


@pytest.fixture
def notes_cwd(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "notes").mkdir()
    return tmp_path


def test_counts_only_readable_files(notes_cwd: Path) -> None:
    _write(notes_cwd / "notes" / "a.txt", "x")
    _write(notes_cwd / "notes" / "b.txt", "y")
    assert count_readable(["a.txt", "b.txt", "missing.txt"]) == 2


def test_empty_list_counts_zero(notes_cwd: Path) -> None:
    assert count_readable([]) == 0


def test_relative_traversal_not_counted(notes_cwd: Path) -> None:
    _write(notes_cwd / "secret.txt", "s")
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0


def test_absolute_path_not_counted(notes_cwd: Path) -> None:
    secret = notes_cwd / "secret.txt"
    _write(secret, "s")
    assert count_readable([str(secret)]) == 0


def test_directory_not_counted(notes_cwd: Path) -> None:
    (notes_cwd / "notes" / "sub").mkdir()
    assert count_readable(["sub"]) == 0


def test_symlink_escape_not_counted(notes_cwd: Path) -> None:
    secret = notes_cwd / "secret.txt"
    _write(secret, "s")
    try:
        os.symlink(secret, notes_cwd / "notes" / "link.txt")
    except OSError:
        pytest.skip("symlinks not supported here")
    assert count_readable(["link.txt"]) == 0


def test_read_note_returns_contents(notes_cwd: Path) -> None:
    _write(notes_cwd / "notes" / "a.txt", "hello")
    assert read_note("a.txt") == "hello"


def test_read_note_missing_is_empty(notes_cwd: Path) -> None:
    assert read_note("nope.txt") == ""


def test_read_note_traversal_is_empty(notes_cwd: Path) -> None:
    _write(notes_cwd / "secret.txt", "s")
    assert read_note("../secret.txt") == ""
